head.script:
// 전역 변수 초기화
scwin.LOGIN_USER_ID = "";
scwin.PJT_ID = "";

/**
 * @method
 * @name scwin.onpageload
 * @description 페이지 로드 시 기본 로그인 사용자 정보와 프로젝트 ID를 설정하고 초기 조회를 수행한다.
 * @example
 * scwin.onpageload();
 */
scwin.onpageload = function () {
    var usrId = $p.getComponentById("mf_pg_header").getWindow().scwin.USER_ID; // 헤더에서 조회
    var selPjtId = $p.getParentWindow().scwin.SEL_PJT_ID; // 메인 페이지에서 조회
    scwin.LOGIN_USER_ID = usrId;
    scwin.PJT_ID = selPjtId;

    // 검색 조건 초기화
    dmp_pugVo.set("pjtId", scwin.PJT_ID);

    // 초기 데이터 조회
    scwin.btn_search_onclick();
};

/**
 * @method
 * @name scwin.btn_search_onclick
 * @description 조회 버튼 클릭 시 페이지 번호 초기화 후 유저 그룹 및 프로젝트 유저 그룹 목록을 조회한다.
 * @param {Event} e - 클릭 이벤트 객체
 * @example
 * <w2:trigger id="btn_search" onClick="scwin.btn_search_onclick" />
 */
scwin.btn_search_onclick = function (e) {
    dmp_pugVo.set("pageIndex", "1");
    pgl_pugList.setSelectedIndex(1);

    $c.sbm.execute(sbm_selectGrpVoList);  // 메뉴 그룹 조회
    $c.sbm.execute(sbm_selectPugVoList);  // 유저 그룹 매핑 목록 조회
};

/**
 * @method
 * @name scwin.sbm_pugList_submitdone
 * @description 프로젝트 유저 그룹 목록 조회 완료 후 결과를 그리드에 반영하고 페이지 정보를 갱신한다.
 * @param {Object} e - 서브미션 완료 이벤트 객체
 * @example
 * <w2:submission id="sbm_selectPugVoList" submitDone="scwin.sbm_pugList_submitdone" />
 */
scwin.sbm_pugList_submitdone = function (e) {
    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (elHeader == null || elHeader === "" || elHeader === "undefiend" || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    spn_listCnt.setLabel(elData.totalCount);
    dlt_pugVoList.setJSON(elData.pugVoList);

    var totalPageCount = Math.ceil(elData.totalCount / dmp_pugVo.get("pageSize"));
    pgl_pugList.setCount(totalPageCount);
    spn_totalPageCount.setValue(totalPageCount);
    spn_pageIndex.setValue(dmp_pugVo.get("pageIndex"));
    pgl_pugList.setSelectedIndex(dmp_pugVo.get("pageIndex"));

    let num = Number(dmp_pugVo.get("pageIndex"));
    num = (num - 1) * 10;
    grd_list.setStartRowNumber(num);
};

/**
 * @method
 * @name scwin.pgl_pugList_onclick
 * @description 페이지 네비게이터 클릭 시 선택한 페이지 번호로 데이터를 재조회한다.
 * @param {Number} idx - 선택된 페이지 번호
 * @example
 * <w2:pagingNavigator id="pgl_pugList" onClick="scwin.pgl_pugList_onclick" />
 */
scwin.pgl_pugList_onclick = function (idx) {
    dmp_pugVo.set("pageIndex", idx);
    $c.sbm.execute($p, sbm_selectPugVoList);
};

/**
 * @method
 * @name scwin.sbm_selectGrpVoList_submitdone
 * @description 그룹 목록 조회 완료 후 결과를 데이터리스트에 반영한다.
 * @param {Object} e - 서브미션 완료 이벤트 객체
 * @example
 * <w2:submission id="sbm_selectGrpVoList" submitDone="scwin.sbm_selectGrpVoList_submitdone" />
 */
scwin.sbm_selectGrpVoList_submitdone = function (e) {
    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (elHeader == null || elHeader === "" || elHeader === "undefiend" || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    dlt_grpVoList.setJSON(elData.pugVoList);
};

/**
 * @method
 * @name scwin.btn_delete_onclick
 * @description 삭제 버튼 클릭 시 체크된 행을 데이터리스트에서 제거한다.
 * @param {Event} e - 클릭 이벤트 객체
 * @example
 * <w2:trigger id="btn_delete" onClick="scwin.btn_delete_onclick" />
 */
scwin.btn_delete_onclick = function (e) {
    let chkArrIdx = grd_list.getCheckedIndex("chk");
    dlt_pugVoList.deleteRows(chkArrIdx);
};

/**
 * @method
 * @name scwin.btn_save_onclick
 * @description 저장 버튼 클릭 시 변경된 데이터(입력/수정/삭제)를 서버로 전송한다.
 * @param {Event} e - 클릭 이벤트 객체
 * @example
 * <w2:trigger id="btn_save" onClick="scwin.btn_save_onclick" />
 */
scwin.btn_save_onclick = function (e) {
    let reqObj = {
        "elData": { "pugVoList": dlt_pugVoList.getModifiedJSON() }
    };
    $c.sbm.execute(sbm_savePugVoList, reqObj);
};

/**
 * @method
 * @name scwin.sbm_savePugVoList_submitdone
 * @description 저장 완료 후 결과 메시지를 출력하고 목록을 재조회한다.
 * @param {Object} e - 서브미션 완료 이벤트 객체
 * @example
 * <w2:submission id="sbm_savePugVoList" submitDone="scwin.sbm_savePugVoList_submitdone" />
 */
scwin.sbm_savePugVoList_submitdone = function (e) {
    var elHeader = e.responseJSON.elHeader;

    if (elHeader == null || elHeader === "" || elHeader === "undefiend" || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    $c.win.alert("통합 수정되었습니다.");
    scwin.btn_search_onclick();
};

/**
 * @method
 * @name scwin.dlt_pugVoList_oncelldatachange
 * @description 그리드 셀 데이터 변경 시 입력한 그룹명이 유효할 경우 자동으로 grpId를 매핑한다.
 * @param {Object} info - 변경된 셀 정보 객체
 * @example
 * <w2:dataList id="dlt_pugVoList" onCellDataChange="scwin.dlt_pugVoList_oncelldatachange" />
 */
scwin.dlt_pugVoList_oncelldatachange = function (info) {
    if (info.colID === "grpName" && info.newValue) {
        let matched = $c.data.getMatchedJSON(dlt_grpVoList, {
            columnId: "grpName",
            operator: "==",
            value: info.newValue
        });

        if (matched.length > 0) {
            dlt_pugVoList.setCellData(info.rowIndex, "grpId", matched[0].grpId);
        }
    }
};

/**
 * @method
 * @name scwin.btn_new_onclick
 * @description 신규 등록 버튼 클릭 시 팝업을 띄워 사용자 그룹을 추가한다.
 * @param {Event} e - 클릭 이벤트 객체
 * @example
 * <w2:trigger id="btn_new" onClick="scwin.btn_new_onclick" />
 */
scwin.btn_new_onclick = function (e) {
    var popupData = {
        "type": "json",
        "name": "params",
        "data": {
            "pjtId": scwin.PJT_ID
        }
    };

    const screenWidth = window.innerWidth;
    const screenHeight = window.innerHeight;
    const popupWidth = 800;
    const popupHeight = 800;
    const popupLeft = (screenWidth - popupWidth) / 2 + "px";
    const popupTop = (screenHeight - popupHeight) / 2 + "px";

    const options = {
        id: "pjt_detail",
        type: "wframePopup",
        width: popupWidth + "px",
        height: popupHeight + "px",
        top: popupTop,
        left: popupLeft,
        popupName: "인력관리 상세 팝업",
        modal: true,
        closeAction: "scwin.popup_closeAction",
        dataObject: popupData
    };

    $p.openPopup("/InsWebApp/ui/pug/PugDetail.xml", options);
};

/**
 * @method
 * @name scwin.popup_closeAction
 * @description 팝업 닫기 시 재조회 처리
 * @param {String} argRuntimeID - 팝업의 실행 ID
 * @param {Object} argJsnInfo - 팝업 닫힘 시 전달된 정보
 * @returns {Boolean} 팝업 닫기 여부
 */
scwin.popup_closeAction = function (argRuntimeID, argJsnInfo) {
    var popObj = $p.getPopupWindow(argRuntimeID);
    // 검색 조건 초기화
    dmp_pugVo.set("pjtId", scwin.PJT_ID);

    scwin.btn_search_onclick();
    return true;
};
